
function rememberTechnician(profile){if(!technicianProfileKey)return;try{localStorage.setItem(technicianProfileKey,JSON.stringify(profile))}catch{message('No se pudo conservar el perfil técnico en este dispositivo.',true)}}
function applyTechnician(){if(!frameReady||!technicianProfileKey||typeof outgoingReportId!=='undefined'&&outgoingReportId)return;try{const p=JSON.parse(localStorage.getItem(technicianProfileKey)||'null');if(!p)return;frame().applyTechnicianProfile(p)}catch{}}
function formatRut(value){const raw=String(value||'').replace(/[^0-9kK]/g,'').toUpperCase().slice(0,9);if(raw.length<2)return raw;const body=raw.slice(0,-1);return body.replace(/\B(?=(\d{3})+(?!\d))/g,'.')+'-'+raw.at(-1)}
function formatRutInput(input){const pos=input.selectionStart,old=input.value,count=old.slice(0,pos??old.length).replace(/[^0-9kK]/g,'').length;input.value=formatRut(old);if(pos!==null){let i=0,n=0;while(i<input.value.length&&n<count){if(/[0-9K]/.test(input.value[i]))n++;i++}input.setSelectionRange(i,i)}}
const $=id=>document.getElementById(id);let reportEquipmentId=null,client=null,locations=[],equipment=[],kind='',frameReady=false,technicianProfileKey='',reportNumbers=null,currentUser=null,currentReportNames={},currentPolicy=null;
