async function search(){const term=$('rutSearch').value.trim(),version=++searchVersion;client=null;$('locationArea').hidden=true;$('equipmentArea').hidden=true;$('startReport').hidden=true;$('clientResult').hidden=true;$('searchMatches').replaceChildren();if(term.length<2)return;const matches=await api('clients?q='+encodeURIComponent(term));if(version!==searchVersion)return;const raw=term.replace(/[^0-9kK]/g,'').toUpperCase(),exact=matches.find(c=>c.rut===raw);if(exact){await selectClient(exact);return}if(!matches.length){message('Cliente no encontrado. Puedes registrar uno nuevo.');return}for(const c of matches){const b=document.createElement('button');b.type='button';b.textContent=c.name+' · '+formatRut(c.rut);b.style.cssText='display:block;width:100%;text-align:left;margin-top:8px';b.onclick=()=>run(b,()=>selectClient(c));$('searchMatches').append(b);}}

