function openEntry(type){if(type==='location'&&!client)return message('Primero busca o registra un cliente.',true);if(type==='equipment'&&!$('locationSelect').value)return message('Selecciona una dirección.',true);kind=type;$('entryTitle').textContent=specs[type].title;$('entryFields').replaceChildren();$('entryError').textContent='';for(const [key,title,placeholder]of specs[type].fields){const label=document.createElement('label');const required=type!=='equipment'||key==='name';label.textContent=title+(required?' *':' (opcional)');const input=document.createElement('input');input.name=key;input.required=required;input.maxLength=180;input.placeholder=placeholder;if(type==='client'&&key==='rut')input.value=/^[0-9.kK-]+$/.test($('rutSearch').value)?$('rutSearch').value:'';label.append(input);$('entryFields').append(label)}$('entryDialog').showModal();if(type==='location')api('client-contacts?client='+encodeURIComponent(client.id)).then(rows=>{if(!rows.length)return;const select=document.createElement('select');select.add(new Option('Contacto del cliente (opcional)',''));for(const [i,c]of rows.entries())select.add(new Option(c.name+' · '+c.phone,i));select.onchange=()=>{const c=rows[Number(select.value)];if(select.value!==''&&c){$('entryForm').elements.contact.value=c.name;$('entryForm').elements.phone.value=c.phone;}};$('entryFields').prepend(select);}).catch(()=>{});}
