function applyNames(names){currentReportNames=names;for(const option of $('reportType').options)if(names[option.value])option.textContent=names[option.value];for(const [k,id]of Object.entries({inspectiva:'nameInspectiva',filtros:'nameFiltros',levantamiento:'nameLevantamiento'}))$(id).value=names[k]||'';if(frameReady&&frame().setReportNames)frame().setReportNames(names);}
