async function loadUsers(){const rows=await api('admin/users');$('adminUsers').replaceChildren();for(const u of rows){const row=document.createElement('div');row.className='selection';const text=document.createElement('div');text.textContent=u.name+' · '+u.email+' · '+(u.role==='admin'?'Administrador':'Técnico')+' · '+(u.active?'Activo':'Desactivado')+' · Letra '+(u.letter||'sin asignar');const edit=document.createElement('button');edit.type='button';edit.textContent='Editar';edit.onclick=()=>{$('userName').value=u.name;$('userEmail').value=u.email;$('userEmail').readOnly=true;$('userRole').value=u.role;$('userActive').value=String(Boolean(u.active));$('userStatus').textContent='';$('userForm').scrollIntoView({behavior:'smooth'});};row.append(text,edit);$('adminUsers').append(row);}}
