let masterEditing=null;
$('masterNav').onclick=()=>run($('masterNav'),async()=>{const bot=await api('master/bot');$('botEnabledToggle').checked=bot.enabled;$('botAiToggle').checked=bot.aiEnabled===true;$('botTestToggle').checked=bot.testEnabled===true;$('botDraftToggle').checked=bot.draftEnabled===true;$('botAiEndpoint').value=bot.endpoint||'';const d=await api('master/settings');const sending=await api('master/review-enabled');$('reviewEnabledToggle').checked=sending.enabled;$('reviewEnabledStatus').textContent='';masterEditing=d.settings;$('masterFields').replaceChildren();for(const [type,p]of Object.entries(masterEditing.types)){const section=document.createElement('section');section.className='card';const h=document.createElement('h2');h.textContent=currentReportNames[type];section.append(h);for(const [key,title]of [['descriptionFontPt','Observaciones generales / descripción (pt)'],['customerFontPt','Comentarios del cliente (pt)']]){const l=document.createElement('label');l.textContent=title;const n=document.createElement('input');n.type='number';n.min='8';n.max='12';n.step='0.5';n.value=p[key]??10;n.oninput=()=>p[key]=n.value===''?null:Number(n.value);l.append(n);section.append(l);}const fontHint=document.createElement('p');fontHint.textContent='Entre 8 y 12 puntos. Una letra mayor permite menos texto dentro del recuadro.';section.append(fontHint);const max=document.createElement('label');max.textContent='Máximo de fotos (0 a 20)';const input=document.createElement('input');input.type='number';input.min='0';input.max='20';input.value=p.maxPhotos;input.oninput=()=>p.maxPhotos=Number(input.value);max.append(input);section.append(max);const flag=(label,value,change)=>{const l=document.createElement('label'),c=document.createElement('input');c.type='checkbox';c.style.width='auto';c.checked=value;c.onchange=()=>change(c.checked);l.append(c,document.createTextNode(' '+label));return l};section.append(flag('Exigir al menos una foto',p.photosRequired,v=>p.photosRequired=v),flag('Exigir comentarios en las fotos',p.photoCommentsRequired,v=>p.photoCommentsRequired=v));for(const group of [...new Set(d.fields.map(f=>f.group))]){if(group==='Levantamiento'&&type!=='levantamiento')continue;const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent=group;details.append(summary);for(const f of d.fields.filter(f=>f.group===group))details.append(flag(f.label,p.required[f.id],v=>p.required[f.id]=v));section.append(details)}$('masterFields').append(section)}$('masterStatus').textContent='';show('master');await loadMasterAccounts();try{await GensetCatalogDrive.load()}catch{}});
