// Durable retry snapshots are separate from the technician's form draft.
let activeReview=null,driveSettings=null,folderContext=null;
async function reviewStore(key,value){return new Promise((resolve,reject)=>{const open=indexedDB.open('genset-training-review-retries',1);open.onupgradeneeded=()=>open.result.createObjectStore('items');open.onerror=()=>reject(Error('No se pudo guardar el envío para reintentar.'));open.onsuccess=()=>{const db=open.result,t=db.transaction('items',value===undefined?'readonly':'readwrite'),st=t.objectStore('items');let result;if(value===undefined){const req=st.get(key);req.onsuccess=()=>result=req.result;}else if(value===null)st.delete(key);else st.put(value,key);t.oncomplete=()=>{db.close();resolve(result)};t.onerror=()=>{db.close();reject(Error('No se pudo guardar el envío. No cierres la aplicación.'))}}})}
function blobBase64(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(blob)})}
async function clearSentReport(key){const saved=await reviewStore(key),matches=saved?.package?.values?.numero===frame().data().values.numero;await confirmReportReceipt(saved);const id=matches?frame().data().localReportId:null;if(id)await GensetDrafts.remove(pendingKey(id));if(matches)await frame().clearSubmittedDraft();await reviewStore(key,null);reportEquipmentId=null;$('resumeCard').hidden=true;$('resumeLabel').textContent='';$('editorTitle').textContent='';$('saveHint').textContent='';show('client');}
async function clientReviewCopy(attempt){const blob=new Blob([Uint8Array.from(atob(attempt.clientPdf),c=>c.charCodeAt(0))],{type:'application/pdf'}),name='Cliente-'+(attempt.package.values.numero||attempt.id).replace(/[^a-zA-Z0-9_-]/g,'_')+'.pdf';if(window.GensetNative)await window.GensetNative.savePdf(blob,name);else{const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}}
$('submitReview').onclick=()=>run($('submitReview'),async()=>{
 if(!frameReady||activeReview||outgoingReportId)throw Error('Abre un informe técnico editable.');
 if(!frame().validateRequired())return;
 if(!confirm('Estás enviando el informe a revisión. ¿Deseas continuar?'))return;
 await saveCurrentPending();const id=frame().data().localReportId;
 if(!await sendPending(id))throw Error('El informe tiene requisitos pendientes.');frame().setReviewLocked(false);await frame().clearSubmittedDraft();reportEquipmentId=null;show('client');message('Informe enviado a revisión. Borrador local eliminado.');
});

