let botQuestion='',botBusy=false,botEquipment='',botToken='',botHistory=[];
function botLine(text,role='assistant'){const p=document.createElement('p');p.className='bot-message '+(role==='user'?'bot-user':'bot-assistant');p.textContent=text;$('botConversation').append(p);$('botConversation').scrollTop=$('botConversation').scrollHeight;}
const botMeasurements=[];
function botModelBreakdown(name,d){if(!d)return '\n'+name+': actualiza el puente para ver el detalle.';const ms=n=>n==null?'no disponible':(n/1000).toFixed(2)+' s';return '\n\n'+name+' · '+(d.model||'modelo local')+'\nStreaming: '+(d.streamed?'sí':'no')+'\nCabeceras LM: '+ms(d.headersMs)+'\nPrimer evento: '+ms(d.firstEventMs)+'\nPrimer texto del modelo: '+ms(d.firstContentMs)+'\nDesde primer texto hasta fin: '+ms(d.generationMs)+'\nTokens entrada / salida: '+(d.promptTokens??'no disponible')+' / '+(d.completionTokens??'no disponible')+'\nCaracteres instrucciones / entrada / salida: '+d.systemChars+' / '+d.inputChars+' / '+d.outputChars+'\nVelocidad de salida (tokens/s aprox.): '+(d.completionTokens>1&&d.generationMs>0?((d.completionTokens-1)*1000/d.generationMs).toFixed(1):'no disponible')+'\nPreguntas de historial: '+d.historyCount+'\nValidación: '+ms(d.validationMs)+'\nConsultas correctas anteriores del puente: '+d.successfulCallsBefore+'\nInactividad previa: '+ms(d.idleMs)+'\nCarga, cola interna, GPU y preparación del prompt: no separables con esta API.';}
function botTiming(t,clientMs,drafting){botMeasurements.push({at:new Date().toISOString(),...t,clientTotalMs:clientMs,drafting});if(botMeasurements.length>30)botMeasurements.shift();$('botDiagDownload').hidden=false;const sec=n=>(Math.max(0,n)/1000).toFixed(2)+' s';const model=n=>n===null||n===undefined?'no disponible (actualiza puente)':sec(n);const details=document.createElement('details'),summary=document.createElement('summary'),text=document.createElement('p');summary.textContent='Diagnóstico · '+sec(clientMs)+' total · '+(drafting==='ai'?'redacción IA':drafting==='off'?'respuesta directa':'respuesta directa de respaldo');text.style.whiteSpace='pre-line';const stages=[['Interpretación / ida y vuelta',t.interpretationRoundTripMs],['Lectura D1',t.d1ReadMs],['Procesamiento consulta',t.queryProcessingMs],['Redacción / ida y vuelta',t.draftingRoundTripMs]];const largest=stages.reduce((a,b)=>b[1]>a[1]?b:a,stages[0]);text.textContent='Mayor etapa medida: '+largest[0]+'\n'+stages.map(([name,ms])=>name+': '+sec(ms)).join('\n')+'\nModelo interpretación: '+model(t.interpretationModelMs)+'\nModelo redacción: '+model(t.draftingModelMs)+(t.interpretationModelMs==null?'':'\nPuente y comunicación de interpretación (aprox.): '+sec(t.interpretationRoundTripMs-t.interpretationModelMs))+(t.draftingModelMs==null?'':'\nPuente y comunicación de redacción (aprox.): '+sec(t.draftingRoundTripMs-t.draftingModelMs))+'\nTotal Worker: '+sec(t.workerTotalMs)+'\nApp ↔ Worker y procesamiento del cliente (aprox.): '+sec(clientMs-t.workerTotalMs)+'\nEstado redacción: '+drafting+'\nConsulta: '+t.requestId+'\nLas idas y vueltas incluyen el modelo; no se deben sumar otra vez sus tiempos.';text.textContent+=botModelBreakdown('Interpretación',t.interpretationDetail)+botModelBreakdown('Redacción',t.draftingDetail);details.append(summary,text);$('botConversation').append(details);}
async function askBot(equipment,selectionQuestion,selectionToken){if(botBusy)return;const question=selectionQuestion||(equipment?botQuestion:$('botQuestion').value.trim());if(!question)return;botBusy=true;$('botSend').disabled=true;try{if(!equipment){botQuestion=question;botLine(question,'user');if(!selectionQuestion)$('botQuestion').value='';$('botQuestion').focus();}$('botEngine').textContent='Consultando…';const queryStart=Date.now();const d=await api('bot/query',{method:'POST',body:JSON.stringify({question,history:botHistory.slice(-8),...((selectionToken||botToken)?{conversationToken:selectionToken||botToken}:{}),...(equipment?{equipment}:botEquipment?{context:botEquipment}:{})})});const clientTotalMs=Date.now()-queryStart;botLine(d.message);if(d.timing)botTiming(d.timing,clientTotalMs,d.drafting);if(d.conversationToken){botToken=d.conversationToken;if(!d.equipment)botEquipment='';}if(!equipment){botHistory.push(question);botHistory=botHistory.slice(-8);}if(d.engine)$('botEngine').textContent=d.engine==='ia_local'?'IA local · resultado de D1'+(d.preview?' · prueba Máster':''):'Buscador básico · '+(d.engineStatus||'IA no disponible');for(const r of d.records||[])botLine(r.label+' · '+r.detail);if(!d.narrative&&d.comparison?.length){const table=document.createElement('table');for(const r of d.comparison){const tr=document.createElement('tr'),name=document.createElement('th');name.textContent=r.equipment.code+' · '+r.equipment.equipment+' · '+r.equipment.address;tr.append(name);for(const f of r.fields){const td=document.createElement('td');td.textContent=f.label+': '+f.value;tr.append(td);}table.append(tr);}$('botConversation').append(table);}if(d.hasMore)botLine('Hay más resultados. Puedes pedir la siguiente página.');for(const c of d.choices||[]){const button=document.createElement('button');button.type='button';button.textContent=c.code+' · '+c.client+' · '+c.equipment+' · '+c.address+(c.engineModel?' · Motor '+c.engineModel:'')+(c.engineSerial?' · Serie motor '+c.engineSerial:'');button.onclick=()=>askBot(c.id,question,d.conversationToken||'');$('botConversation').append(button);}if(d.equipment){botEquipment=d.equipment.id||'';if(!d.narrative){botLine(d.equipment.code+' · '+d.equipment.client+' · '+d.equipment.equipment+' · '+d.equipment.address);const list=document.createElement('dl');for(const f of d.fields){const title=document.createElement('dt'),value=document.createElement('dd');title.textContent=f.label;value.textContent=f.value;list.append(title,value);}$('botConversation').append(list);}}$('botConversation').scrollTop=$('botConversation').scrollHeight;}catch(e){botLine(e.message);const retry=document.createElement('button');retry.type='button';retry.textContent='Reintentar esta pregunta';retry.onclick=()=>askBot(equipment,question,selectionToken||botToken);$('botConversation').append(retry);}finally{botBusy=false;$('botSend').disabled=false;}}
$('botForm').onsubmit=e=>{e.preventDefault();askBot();};$('botClear').onclick=()=>{if(botBusy)return;botQuestion='';botEquipment='';botToken='';botHistory=[];$('botQuestion').value='';$('botConversation').replaceChildren();$('botQuestion').focus();};

document.addEventListener('input',e=>{if(kind==='client'&&e.target.name==='name')e.target.value=e.target.value.toUpperCase();if(e.target.name==='power')e.target.value=e.target.value.replace(/kva|kw|hz|v\b/gi,v=>v.toUpperCase());});

// Independent, account-scoped reports. Every draft retains its original policy and ID.
let outgoingReportId='';let pendingBusy=false,pendingSaveChain=Promise.resolve();const pendingSending=new Set();let pendingBulkCopies=null,pendingConfirmedReceipt=null;
async function expectedReportHash(attempt){const p=structuredClone(attempt.package);delete p.signatures?.sig_jefe;delete p.assignment;const text=JSON.stringify({format:'genset-training-report',schemaVersion:1,appVersion:'1.4.0',id:attempt.id,technician:currentUser.email,submitted:typeof attempt.submitted==='string'?attempt.submitted.slice(0,40):'',report:p});return [...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)))].map(x=>x.toString(16).padStart(2,'0')).join('');}
async function confirmReportReceipt(attempt,post){if(!attempt?.id||!attempt.package)throw Error('Falta información del envío. Conserva el borrador y revisa los últimos envíos.');if(post&&(post.id!==attempt.id||!['pending','approving','approved'].includes(post.status)))throw Error('El servidor no confirmó un informe para supervisión. Se conserva el borrador.');const receipt=await api('reports/status?id='+encodeURIComponent(attempt.id));if(receipt.id!==attempt.id||receipt.technician!==currentUser.email||receipt.ready!==true||!['pending','approving','approved'].includes(receipt.status)||receipt.number!==String(attempt.package.values.numero||'').slice(0,180)||receipt.hash!==await expectedReportHash(attempt)||!receipt.destination||post?.destination&&post.destination!==receipt.destination)throw Error('El acuse no coincide con el informe o no está disponible para supervisión. Se conserva el borrador.');return receipt;}
function batchLogKey(){return 'genset-training-batch-log:'+encodeURIComponent(currentUser.email.toLowerCase());}
function renderBatchResults(log,copies=[]){const host=$('pendingBatchResults');host.replaceChildren();if(!log?.results?.length)return;const h=document.createElement('h3');h.textContent='Resultado del último lote'+(log.at?' · '+new Date(log.at).toLocaleString():'');host.append(h);for(const row of log.results){const p=document.createElement('p');p.textContent=row.number+' · '+row.status+(row.reason?' · '+row.reason:'')+(row.destination?' · Destino '+row.destination.slice(0,8):'');host.append(p);}for(const copy of copies){const b=document.createElement('button');b.type='button';b.textContent='Copia cliente · '+copy.package.values.numero;b.onclick=()=>run(b,()=>clientReviewCopy(copy));host.append(b);}}
function pendingPrefix(){if(!currentUser)throw Error('Inicia sesión.');return 'genset-training-pending:'+encodeURIComponent(currentUser.email.toLowerCase())+':';}
function pendingKey(id){return pendingPrefix()+id;}
function savePendingSnapshot(snapshot){if(snapshot.assignmentViewOnly||!currentUser||activeReview||typeof outgoingReportId!=='undefined'&&outgoingReportId||pendingBusy||!snapshot.values?.numero||pendingSending.has(snapshot.localReportId))return Promise.resolve();const copy=structuredClone(snapshot),key=pendingKey(copy.localReportId);if(!copy.localReportId)return Promise.resolve();const task=pendingSaveChain.catch(()=>{}).then(async()=>{const old=await GensetDrafts.read(key);if(old?.sent||old?.attempt||old?.assignmentOut)return;await GensetDrafts.save(key,{...old,snapshot:copy,status:'Guardado',saved:new Date().toISOString()});$('resumeCard').hidden=false;});pendingSaveChain=task;return task;}

async function saveCurrentPending(){if(!frameReady||activeReview||outgoingReportId||frame().data().assignmentViewOnly)return;await frame().saveDraft();const d=frame().data();if(d.values.numero)await savePendingSnapshot(d);}
async function recoverSentPending(){for(const r of await GensetDrafts.list(pendingPrefix()))if(r.snapshot?.sent){const entry=r.snapshot;try{const receipt=await confirmReportReceipt(entry.attempt);await GensetDrafts.save('genset-training-receipt:'+encodeURIComponent(currentUser.email)+':'+receipt.id,receipt);if(frame().data().localReportId===entry.snapshot.localReportId)await frame().clearSubmittedDraft();await GensetDrafts.remove(r.key);}catch(e){entry.sent=false;if(entry.attempt)entry.attempt.sent=false;entry.status='Envío sin verificar: '+e.message;await GensetDrafts.save(r.key,entry);}}}

function syncReportActions(){const assigning=typeof outgoingReportId!=='undefined'&&!!outgoingReportId;const reviewing=typeof activeReview!=='undefined'&&!!activeReview;const enabled=typeof reviewSendingEnabled!=='undefined'&&reviewSendingEnabled;for(const id of ['saveReport','saveWord'])$(id).hidden=enabled&&!reviewing;$('saveDraftButton').hidden=reviewing||assigning;$('assignReportButton').hidden=reviewing||assigning||!(currentUser?.role==='admin'||currentUser?.isMaster);if(assigning){$('submitReview').hidden=true;$('saveReport').hidden=true;$('saveWord').hidden=true;}if(assigning&&frameReady)frame().setReviewLocked(true);if(frameReady&&frame().setManualDownloads)frame().setManualDownloads(!enabled||reviewing);}
async function openPending(id){const r=await GensetDrafts.read(pendingKey(id));if(!r||r.sent)throw Error('El informe ya no está pendiente.');if(activeReview)frame().exitReview();activeReview=null;outgoingReportId=r.assignmentOut?id:'';frame().restore({...r.attempt?.package||r.snapshot,localReportId:id});frame().setReviewLocked(!!r.attempt||!!r.assignmentOut);frame().update();$('reviewStatus').textContent=r.attempt?'Envío pendiente de confirmar. Se conserva su contenido original para reintentar sin duplicarlo.':'';reportEquipmentId=r.snapshot.catalogEquipmentId;$('editorTitle').textContent=r.snapshot.values.generador||'Informe pendiente';$('catalogSurveySave').hidden=r.snapshot.reportType!=='levantamiento';$('approveReview').hidden=true;$('submitReview').hidden=!!r.assignmentOut;show('editor');}
async function showPending(){if(!frameReady)throw Error('Espera a que cargue el formulario.');show('pending');$('localPendingList').replaceChildren();const rows=await GensetDrafts.list(pendingPrefix());void loadAssignments();renderBatchResults(await GensetDrafts.read(batchLogKey()));await renderClientCopies();$('pendingStatus').textContent=rows.length?'Guardados solamente en esta cuenta y dispositivo.':'No hay informes guardados.';$('sendAllPending').disabled=!reviewSendingEnabled||pendingBusy;for(const r of rows){const entry=r.snapshot;if(entry.sent)continue;const d=entry.snapshot,card=document.createElement('div');card.className='card';const title=document.createElement('h2');title.textContent=d.values.numero+' · '+d.values.generador;const text=document.createElement('p');text.textContent=d.values.cliente+' · '+d.values.direccion+' · '+(entry.status||'Guardado')+(d.assignment?' · Asignado por '+d.assignment.assignedBy:'');const open=document.createElement('button');open.textContent='Continuar';open.onclick=()=>run(open,async()=>{await saveCurrentPending();await openPending(d.localReportId);});const send=document.createElement('button');send.textContent='Enviar a revisión';send.disabled=!reviewSendingEnabled||pendingBusy||!!entry.assignmentOut;send.onclick=()=>run(send,()=>sendSelected([d.localReportId]));card.append(title,text,open,send);const remove=document.createElement('button');remove.textContent='Eliminar del dispositivo';remove.disabled=pendingBusy||!!entry.assignmentOut||!!d.assignment;remove.onclick=()=>run(remove,()=>deleteLocalPending(d.localReportId));card.append(remove);if(entry.assignmentOut?.state==='preparing'){const retry=document.createElement('button');retry.textContent='Reintentar asignación';retry.onclick=()=>run(retry,()=>transmitAssignment(d.localReportId));card.append(retry);}$('localPendingList').append(card);}}
async function sendPending(id){if(pendingSending.has(id))throw Error('Este informe ya está en proceso.');pendingSending.add(id);const main=document.querySelector('main'),nav=document.querySelector('nav');if(main)main.inert=true;if(nav)nav.inert=true;try{submissionProgress('prepare','');await pendingSaveChain;const result=await sendPendingEntry(id);if(!result&&!pendingBulkCopies)submissionClose();return result;}catch(e){if(!pendingBulkCopies)submissionFailed(e.message);throw e;}finally{pendingSending.delete(id);if(main)main.inert=false;if(nav)nav.inert=false;}}
async function sendPendingEntry(id){const key=pendingKey(id);let entry=await GensetDrafts.read(key);if(!entry)return false;if(entry.assignmentOut)return false;if(entry.sent&&!entry.attempt){entry.status='No hay acuse verificable. Conserva este borrador y revisa los últimos envíos.';await GensetDrafts.save(key,entry);return false;}const setting=await api('me');setReviewSending(setting.reviewEnabled===true);if(!setting.reviewEnabled)throw Error('Envío deshabilitado por Máster.');let attempt=entry.attempt;const legacyKey='active:'+currentUser.email,legacy=await reviewStore(legacyKey);if(!attempt&&legacy?.package?.values.numero===entry.snapshot.values.numero){attempt=legacy;entry.attempt=attempt;await GensetDrafts.save(key,entry);await reviewStore(legacyKey,null);}
 if(!attempt){submissionProgress('prepare',entry.snapshot.values.numero);frame().restore(entry.snapshot);const check=frame().pendingCheck();if(!check.valid){entry.status=check.issues.join(' · ')||'Faltan requisitos obligatorios';await GensetDrafts.save(key,entry);return false;}const generated=await frame().downloadPdf({returnBlob:true,returnPackage:true,clientCopy:true});if(!generated?.snapshot)throw Error('No se pudo generar la copia del cliente.');const p=generated.snapshot;delete p.signatures.sig_jefe;attempt={id:crypto.randomUUID(),submitted:new Date().toISOString(),package:p,clientPdf:await blobBase64(generated.blob),sent:false};entry.attempt=attempt;entry.status='Envío preparado';await GensetDrafts.save(key,entry);}frame().setReviewLocked(true);
 try{submissionProgress('upload',attempt.package.values.numero);const post=await api('reports',{method:'POST',body:JSON.stringify({id:attempt.id,submitted:attempt.submitted,package:attempt.package})});submissionProgress('confirm',attempt.package.values.numero);const receipt=await confirmReportReceipt(attempt,post);await saveClientCopy(attempt);await GensetDrafts.save('genset-training-receipt:'+encodeURIComponent(currentUser.email)+':'+receipt.id,receipt);entry.receipt=receipt;pendingConfirmedReceipt=receipt;attempt.sent=true;entry.sent=true;await GensetDrafts.save(key,entry);if(frame().data().localReportId===id){frame().setReviewLocked(false);await frame().clearSubmittedDraft();}await GensetDrafts.remove(key);}catch(e){entry.status='No se confirmó el envío: '+e.message;await GensetDrafts.save(key,entry);throw e;}
 const copy={id:attempt.id,clientPdf:attempt.clientPdf,package:{values:{numero:attempt.package.values.numero}}};if(pendingBulkCopies)pendingBulkCopies.push(copy);else submissionDone([copy]);return true;
}
async function sendSelected(ids){if(pendingBusy)return;if(!confirm('Estás enviando los informes completos a revisión. ¿Deseas continuar?'))return;await saveCurrentPending();pendingBusy=true;pendingBulkCopies=ids.length>1?[]:null;const before=frame().data(),results=[];let sent=0,skipped=0;try{for(const [i,id]of ids.entries()){const entry=await GensetDrafts.read(pendingKey(id)),number=entry?.snapshot?.values?.numero||id;$('pendingStatus').textContent='Enviando '+(i+1)+' de '+ids.length+' · '+number;try{pendingConfirmedReceipt=null;if(await sendPending(id)){sent++;const receipt=pendingConfirmedReceipt;results.push({number,status:'Confirmado para supervisión',...(receipt?{destination:receipt.destination,id:receipt.id}:{})});}else{skipped++;const kept=await GensetDrafts.read(pendingKey(id));results.push({number,status:'No enviado',reason:kept?.status||'Asignado o con requisitos pendientes'});}}catch(e){results.push({number,status:'Sin confirmar · conservado',reason:e.message});if(e.status===401||e.status===403){for(const next of ids.slice(i+1)){const kept=await GensetDrafts.read(pendingKey(next));results.push({number:kept?.snapshot?.values?.numero||next,status:'No intentado · sesión no autorizada'});}break;}}}}finally{const copies=pendingBulkCopies||[];pendingBulkCopies=null;pendingBusy=false;const remaining=before.localReportId?await GensetDrafts.read(pendingKey(before.localReportId)):null;if(remaining){frame().restore({...remaining.attempt?.package||remaining.snapshot,localReportId:before.localReportId});frame().setReviewLocked(!!remaining.attempt||!!remaining.assignmentOut);if(frame().render)frame().render();}else{frame().setReviewLocked(false);await frame().clearSubmittedDraft();}const log={at:new Date().toISOString(),results};await GensetDrafts.save(batchLogKey(),log);await showPending();renderBatchResults(log,copies);if(copies.length)submissionDone(copies);else submissionClose();$('pendingStatus').textContent=sent+' confirmados · '+skipped+' omitidos · '+(results.length-sent-skipped)+' sin confirmar';}}

$('localPendingNav').onclick=()=>run($('localPendingNav'),async()=>{await saveCurrentPending();await showPending();});$('pendingNew').onclick=()=>show('client');$('sendAllPending').onclick=()=>run($('sendAllPending'),async()=>{await saveCurrentPending();await sendSelected((await GensetDrafts.list(pendingPrefix())).map(r=>r.snapshot.snapshot.localReportId));});
$('botBubble').onclick=async()=>{if(!await refreshBotAvailability())return;$('botView').hidden=!$('botView').hidden;$('botBubble').setAttribute('aria-expanded',String(!$('botView').hidden));if(!$('botView').hidden)$('botQuestion').focus();};$('closeBot').onclick=()=>{$('botView').hidden=true;$('botBubble').setAttribute('aria-expanded','false');};

// Assignment metadata augments existing draft entries; the IndexedDB store and keys stay unchanged.
async function refreshAssignedBadge(){try{const rows=await api('assignments');const count=rows.filter(r=>r.recipient===currentUser.email&&r.status==='assigned').length;$('localPendingNav').textContent='Mis informes'+(count?' · '+count+' asignados':'');}catch{}}
async function chooseAssignmentTechnician(){const users=await api('assignments/technicians');if(!users.length)throw Error('No hay técnicos activos registrados.');return new Promise(resolve=>{const dialog=document.createElement('dialog'),title=document.createElement('h2'),select=document.createElement('select'),ok=document.createElement('button'),cancel=document.createElement('button');title.textContent='Asignar a técnico';select.add(new Option('Selecciona un técnico',''));for(const u of users)select.add(new Option((u.name||u.email)+' · '+u.email,u.email));ok.type=cancel.type='button';ok.textContent='Confirmar asignación';cancel.textContent='Cancelar';const finish=v=>{dialog.close();dialog.remove();resolve(v);};ok.onclick=()=>{if(select.value)finish(select.value);};cancel.onclick=()=>finish(null);dialog.oncancel=e=>{e.preventDefault();finish(null);};dialog.append(title,select,ok,cancel);document.querySelector('main').append(dialog);dialog.showModal();});}
async function transmitAssignment(localId){const key=pendingKey(localId),entry=await GensetDrafts.read(key),a=entry?.assignmentOut;if(!a)throw Error('No hay asignación preparada.');if(a.state==='assigned')return;await api('assignments',{method:'POST',body:JSON.stringify({id:a.id,recipient:a.recipient,package:a.package})});a.state='assigned';delete a.package;entry.status='Asignado a '+a.recipient;await GensetDrafts.save(key,entry);if(frameReady&&frame().data().localReportId===localId){outgoingReportId=localId;frame().setReviewLocked(true);syncReportActions();}message('Asignación confirmada. El técnico puede descargarla en Mis informes.');}
$('assignReportButton').onclick=()=>run($('assignReportButton'),async()=>{if(!frameReady||activeReview)throw Error('Abre un informe de terreno.');await saveCurrentPending();const d=frame().data(),key=pendingKey(d.localReportId),entry=await GensetDrafts.read(key);if(!entry||entry.attempt||d.assignment||entry.assignmentOut)throw Error('No se puede asignar un informe recibido, enviado o con una operación pendiente.');const recipient=await chooseAssignmentTechnician();if(!recipient)return;entry.assignmentOut={id:crypto.randomUUID(),recipient,state:'preparing',package:structuredClone(d)};entry.status='Asignación pendiente de confirmar';await GensetDrafts.save(key,entry);outgoingReportId=d.localReportId;frame().setReviewLocked(true);syncReportActions();await transmitAssignment(d.localReportId);});
async function downloadAssignment(row){const claimKey='genset-training-assignment-claim:'+encodeURIComponent(currentUser.email.toLowerCase())+':'+row.id;let claim=await GensetDrafts.read(claimKey);if(!claim){claim={token:crypto.randomUUID()};await GensetDrafts.save(claimKey,claim);}const existing=await GensetDrafts.read(pendingKey(row.id));if(existing?.snapshot?.assignment){await saveCurrentPending();await openPending(row.id);return;}const d=await api('assignments/'+row.id+'/claim',{method:'POST',body:JSON.stringify({claim:claim.token,revision:row.revision})});await GensetDrafts.save(pendingKey(row.id),{snapshot:d.package,status:'Asignado por '+d.assignedBy,saved:new Date().toISOString()});await saveCurrentPending();await openPending(row.id);applyTechnician();await frame().saveDraft();await savePendingSnapshot(frame().data());await refreshAssignedBadge();}
async function loadAssignments(){const host=$('assignmentsList');host.replaceChildren();try{const rows=await api('assignments'),admin=currentUser.role==='admin'||currentUser.isMaster;const local=(await GensetDrafts.list(pendingPrefix())).filter(r=>r.snapshot?.snapshot);for(const r of local){const a=r.snapshot.assignmentOut;if(a&&rows.find(x=>x.id===a.id)?.status==='cancelled'){delete r.snapshot.assignmentOut;r.snapshot.status='Asignación cancelada · borrador conservado';await GensetDrafts.save(r.key,r.snapshot);}}const active=rows.filter(r=>!['submitted','cancelled'].includes(r.status));$('assignmentsStatus').textContent=active.length?'Requiere conexión para descargar. Después puedes continuar sin internet.':'No hay asignaciones activas.';for(const row of active){const card=document.createElement('div'),label=document.createElement('p');card.className='card';label.textContent=row.number+' · '+row.client+' · '+row.equipment+' · Asignado por '+row.creator_name+' · '+({assigned:'Por descargar',claimed:'En trabajo',submitting:'Envío en curso',uploading:'Carga pendiente'}[row.status]||row.status)+(admin?' · Técnico: '+row.recipient:'');card.append(label);if(row.recipient===currentUser.email&&['assigned','claimed'].includes(row.status)){const open=document.createElement('button');open.textContent='Descargar / continuar';open.onclick=()=>run(open,()=>downloadAssignment(row));card.append(open);}if(admin){const view=document.createElement('button');view.textContent='Ver copia asignada';view.onclick=()=>run(view,async()=>{await saveCurrentPending();const d=await api('assignments/'+row.id);outgoingReportId='preview:'+row.id;activeReview=null;frame().restore({...d.package,localReportId:'preview:'+row.id,assignmentViewOnly:true});frame().update();frame().setReviewLocked(true);$('editorTitle').textContent='Asignación · '+row.number;$('submitReview').hidden=true;$('approveReview').hidden=true;show('editor');});card.append(view);if(row.status==='assigned')for(const action of ['reassign','cancel']){const b=document.createElement('button');b.textContent=action==='reassign'?'Reasignar':'Cancelar asignación';b.onclick=()=>run(b,async()=>{const recipient=action==='reassign'?await chooseAssignmentTechnician():null;if(action==='reassign'&&!recipient)return;if(action==='cancel'&&!confirm('¿Cancelar la asignación? El borrador original se conserva.'))return;await api('assignments/'+row.id+'/'+action,{method:'POST',body:JSON.stringify({revision:row.revision,...(recipient?{recipient}:{})})});await loadAssignments();await showPending();});card.append(b);}}host.append(card);}}catch(e){$('assignmentsStatus').textContent='Asignaciones: '+e.message+' Los informes ya descargados siguen en Guardados.';}}
$('refreshAssignments').onclick=()=>run($('refreshAssignments'),async()=>{await loadAssignments();await refreshAssignedBadge();});

$('botDiagDownload').onclick=()=>run($('botDiagDownload'),async()=>{const blob=new Blob([JSON.stringify({diagnosticVersion:2,samples:botMeasurements},null,2)],{type:'application/json'});if(window.GensetNative)await window.GensetNative.savePdf(blob,'Genset-Diagnostico-IA.json');else{const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Genset-Diagnostico-IA.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}});

async function loadReportReceipts(admin=false){const host=$(admin?'reviewReceipts':'pendingReceipts');host.replaceChildren();try{const data=await api(admin?'admin/reviews/receipts':'reports/receipts'),title=document.createElement('p');title.textContent='Destino de recepción: '+data.destination.slice(0,8)+'. Compara este código entre técnico y supervisión si falta un envío.';host.append(title);if(!data.receipts.length){const empty=document.createElement('p');empty.textContent='No hay envíos registrados en este destino.';host.append(empty);}for(const row of data.receipts){const card=document.createElement('div'),text=document.createElement('p');card.className='card';text.textContent=row.number+' · '+row.technician+' · '+({uploading:'Carga incompleta',pending:'Pendiente de supervisión',approving:'En aprobación',approved:'Aprobado'}[row.status]||row.status)+' · '+row.id;card.append(text);if(admin&&!row.ready&&row.status==='uploading'){const recover=document.createElement('button');recover.textContent='Comprobar respaldo en OneDrive';recover.onclick=()=>run(recover,async()=>{await api('admin/reviews/'+row.id+'/recover',{method:'POST',body:'{}'});await loadReviews();await loadReportReceipts(true);message('Respaldo verificado. El informe ya está disponible para supervisión.');});card.append(recover);}host.append(card);}}catch(e){const text=document.createElement('p');text.textContent=e.message;host.append(text);}}
$('pendingReceiptButton').onclick=()=>run($('pendingReceiptButton'),()=>loadReportReceipts());$('reviewReceiptButton').onclick=()=>run($('reviewReceiptButton'),()=>loadReportReceipts(true));

async function deleteLocalPending(id){
 if(pendingBusy||pendingSending.has(id))throw Error('Espera a que termine el envío.');
 await pendingSaveChain;const key=pendingKey(id),entry=await GensetDrafts.read(key);if(!entry)return;
 if(entry.assignmentOut||entry.snapshot?.assignment)throw Error('Un informe asignado requiere resolver su asignación; no se elimina como prueba local.');
 if(!confirm('¿Eliminar del dispositivo el informe '+entry.snapshot.values.numero+' y sus fotos? No se enviará a revisión. Esta acción no borra archivos de OneDrive.'+(entry.attempt?' Hay un envío sin confirmar: su posible recepción en el servidor se conservará.':'')))return;
 pendingSending.add(id);try{await pendingSaveChain;if(frame().data().localReportId===id){frame().setReviewLocked(false);await frame().clearSubmittedDraft();}const legacy=await reviewStore('active:'+currentUser.email);if(legacy?.id&&legacy.id===entry.attempt?.id)await reviewStore('active:'+currentUser.email,null);await GensetDrafts.remove(key);}finally{pendingSending.delete(id);}await showPending();message('Informe eliminado de este dispositivo.');
}
const historyBase='master/onedrive/history';let historyCursor=null,historyFolder='',historyFolderStack=[];
function historyButton(label,action){const b=document.createElement('button');b.type='button';b.textContent=label;b.onclick=()=>run(b,action);return b;}
async function showHistoryPackage(data){if(!frameReady)throw Error('Espera a que cargue el formulario.');await saveCurrentPending();activeReview={id:data.id,history:true};outgoingReportId='';frame().openReview(data.package,'history:'+data.id);frame().setReviewLocked(true);show('editor');$('editorTitle').textContent='Historial · '+data.package.values.numero;$('submitReview').hidden=true;$('approveReview').hidden=true;$('catalogSurveySave').hidden=true;$('saveDraftButton').hidden=true;$('reviewStatus').textContent='Consulta del respaldo. No modifica el informe original ni crea un pendiente.';}
async function loadHistory(more=false){const host=$('masterHistoryList');if(!more){host.replaceChildren();historyCursor=null;}const data=await api(historyBase+(historyCursor?'?before='+encodeURIComponent(historyCursor):''));for(const row of data.reports){const card=document.createElement('div'),p=document.createElement('p');card.className='card';p.textContent=row.number+' · '+row.client+' · '+row.technician+' · '+row.status+' · '+new Date(row.created).toLocaleString();card.append(p,historyButton('Abrir respaldo',()=>api(historyBase+'/'+row.id+'/open').then(showHistoryPackage)));if(row.status==='approved')for(const [kind,label]of [['temporary','Limpiar temporales'],['all','Eliminar respaldos editables']])card.append(historyButton(label,()=>cleanHistory(row,kind)));const actions=data.actions.filter(a=>a.report===row.id);for(const a of actions){const note=document.createElement('p');note.textContent=(a.kind==='all'?'Respaldos editables eliminados':'Temporales limpiados')+' · '+a.actor+' · '+new Date(a.completed).toLocaleString();card.append(note);}host.append(card);}historyCursor=data.next;$('historyMore').hidden=!historyCursor;if(!data.reports.length&&!more)host.textContent='No hay informes registrados. Puedes buscar respaldos en OneDrive.';}
async function cleanHistory(row,kind){const plan=await api(historyBase+'/'+row.id+'/preview',{method:'POST',body:JSON.stringify({kind})});if(!plan.files.length){message('No quedan archivos de ese tipo para eliminar.');return;}const dialog=$('historyDeleteDialog'),list=$('historyDeleteFiles');list.replaceChildren();for(const f of plan.files){const p=document.createElement('p');p.textContent=f.name+' · '+Math.ceil(f.size/1024)+' KB';list.append(p);}$('historyDeleteWarning').textContent='Informe '+row.number+'. Se conservarán PDF y fotografías.'+(kind==='all'?' Al eliminar estos JSON se pierde la reconstrucción editable desde la app.':' Se conservará el JSON aprobado.');$('historyDeleteConfirm').onclick=()=>run($('historyDeleteConfirm'),async()=>{await api(historyBase+'/'+row.id+'/clean',{method:'POST',body:JSON.stringify({token:plan.token})});dialog.close();await loadHistory();message('Limpieza completada. PDF y fotografías conservados.');});dialog.showModal();}
async function scanHistory(folder){const data=await api(historyBase+'/scan'+(folder?'?folder='+encodeURIComponent(folder):''));historyFolder=data.folder;const host=$('historyScanList');host.replaceChildren();const p=document.createElement('p');p.textContent='Carpeta actual: '+historyFolder+' · '+data.files.length+' respaldos. Se consulta solo esta carpeta.';host.append(p);for(const f of data.folders)host.append(historyButton('Abrir carpeta · '+f.name,async()=>{historyFolderStack.push(historyFolder);await scanHistory(f.id);}));for(const f of data.files){const card=document.createElement('div'),t=document.createElement('p');card.className='card';t.textContent=f.name+' · '+Math.ceil(f.size/1024)+' KB';const inspect=()=>api(historyBase+'/inspect',{method:'POST',body:JSON.stringify({folder:historyFolder,item:f.id})});card.append(t,historyButton('Ver respaldo',async()=>showHistoryPackage(await inspect())));if(/-Original\.genset\.json$/i.test(f.name))card.append(historyButton('Recuperar en revisión',async()=>{const d=await inspect();if(d.registered&&d.registered.status!=='uploading')throw Error('Ya está registrado: '+d.registered.status+'. Consúltalo en el historial.');if(!confirm('¿Recuperar el original '+d.package.values.numero+' para supervisión? No lo envíes otra vez desde un informe nuevo.'))return;await api(historyBase+'/restore',{method:'POST',body:JSON.stringify({folder:historyFolder,item:f.id})});await loadHistory();message('Original recuperado para supervisión.');}));host.append(card);}}
$('historyLoad').onclick=()=>run($('historyLoad'),()=>loadHistory());$('historyMore').onclick=()=>run($('historyMore'),()=>loadHistory(true));$('historyScan').onclick=()=>run($('historyScan'),async()=>{historyFolderStack=[];await scanHistory();});$('historyScanBack').onclick=()=>run($('historyScanBack'),()=>scanHistory(historyFolderStack.pop()||'root'));$('historyDeleteCancel').onclick=()=>$('historyDeleteDialog').close();

function submissionController(){return typeof window!=='undefined'?window.GensetSubmission:null;}
function submissionProgress(stage,number){submissionController()?.progress(stage,number);}
function submissionDone(copies){submissionController()?.done(copies,clientReviewCopy);}
function submissionFailed(reason){submissionController()?.failed(reason);}
function submissionClose(){submissionController()?.close();}
function clientCopyPrefix(){return 'genset-training-client-copy:'+encodeURIComponent(currentUser.email.toLowerCase())+':';}
async function saveClientCopy(attempt){await GensetDrafts.save(clientCopyPrefix()+attempt.id,{id:attempt.id,clientPdf:attempt.clientPdf,package:{values:{numero:attempt.package.values.numero}},saved:new Date().toISOString()});}
async function renderClientCopies(){const host=$('pendingClientCopies');if(!host)return;host.replaceChildren();const rows=await GensetDrafts.list(clientCopyPrefix());if(!rows.length)return;const h=document.createElement('h3');h.textContent='Copias del cliente · informes ya enviados';host.append(h);for(const row of rows){const copy=row.snapshot,card=document.createElement('div'),p=document.createElement('p');card.className='card';p.textContent=copy.package.values.numero+' · Envío confirmado';const share=document.createElement('button');share.textContent='Compartir / descargar copia';share.onclick=()=>run(share,()=>clientReviewCopy(copy));const remove=document.createElement('button');remove.textContent='Eliminar copia local';remove.onclick=()=>run(remove,async()=>{if(!confirm('¿Eliminar la copia PDF local de '+copy.package.values.numero+'? No se borra el informe enviado.'))return;await GensetDrafts.remove(row.key);await renderClientCopies();});card.append(p,share,remove);host.append(card);}}
